function DownloadCountDisplay({ slug }: { slug: string }) {
  const { data } = useQuery<{ count: number }>({
    queryKey: [`/api/downloads/${slug}`],
  });
  return (
    <span className="font-mono font-bold text-orange-400">
      {data?.count?.toLocaleString() ?? "—"}
    </span>
  );
}

